class Solution {
    public int minimizeSet(int divisor1, int divisor2, int uniqueCnt1, int uniqueCnt2) {
        long d1 = divisor1, d2 = divisor2;
        long g = gcd(d1, d2);
        long lcm = (d1 / g) * d2;
        long lo = 1, hi = 2000000007L;
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            long c1 = mid - mid / d1;
            long c2 = mid - mid / d2;
            long cb = mid - mid / lcm;
            if (c1 >= uniqueCnt1 && c2 >= uniqueCnt2 && cb >= (long)uniqueCnt1 + uniqueCnt2) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        return (int)lo;
    }
    private long gcd(long a, long b) {
        return b == 0 ? a : gcd(b, a % b);
    }
}

var minimizeSet = function(divisor1, divisor2, uniqueCnt1, uniqueCnt2) {
    const gcd = (a, b) => b === 0n ? a : gcd(b, a % b);
    const d1 = BigInt(divisor1), d2 = BigInt(divisor2);
    const lcm = (d1 / gcd(d1, d2)) * d2;
    const u1 = BigInt(uniqueCnt1), u2 = BigInt(uniqueCnt2);
    let lo = 1n, hi = 2000000007n;
    while (lo < hi) {
        const mid = (lo + hi) / 2n;
        const c1 = mid - mid / d1;
        const c2 = mid - mid / d2;
        const cb = mid - mid / lcm;
        if (c1 >= u1 && c2 >= u2 && cb >= u1 + u2) {
            hi = mid;
        } else {
            lo = mid + 1n;
        }
    }
    return Number(lo);
};
